    Question(id: 'px2_001', category: 'physiology', subcategory: 'muscular', type: 'test', difficulty: 'hard', questionText: 'Kas kasılmasında kalsiyumun bağlandığı düzenleyici protein hangisidir?', options: ['Aktin', 'Miyozin', 'Troponin C', 'Tropomiyozin'], correctAnswer: 'Troponin C', explanation: 'Ca²⁺ troponin C\'ye bağlanır → troponin I konformasyonu değişir → tropomiyozin kayar → aktin üzerindeki miyozin bağlanma yerleri açılır → kas kasılması başlar.'),
    Question(id: 'px2_002', category: 'physiology', subcategory: 'muscular', type: 'test', difficulty: 'medium', questionText: 'Motor birim (motor unit) nedir?', options: ['Tek bir kas lifi', 'Bir motor nöron ve innerve ettiği tüm kas lifleri', 'Nöromüsküler kavşak', 'Sarkomer'], correctAnswer: 'Bir motor nöron ve innerve ettiği tüm kas lifleri', explanation: 'Motor birim, bir alfa motor nöron ve o nöronun innerve ettiği tüm kas liflerinden oluşur. İnce hareketlerde (göz) az, kaba hareketlerde (uyluk) çok lif içerir.'),
    Question(id: 'px2_003', category: 'physiology', subcategory: 'muscular', type: 'test', difficulty: 'hard', questionText: 'Nöromüsküler kavşakta sinyal iletimini sağlayan nörotransmitter hangisidir?', options: ['Noradrenalin', 'Dopamin', 'Asetilkolin', 'Serotonin'], correctAnswer: 'Asetilkolin', explanation: 'İskelet kasının nöromüsküler kavşağında asetilkolin (ACh) kullanılır. ACh nikotinik reseptörlere bağlanır ve kas membranında depolarizasyon başlatır.'),
    Question(id: 'px2_004', category: 'physiology', subcategory: 'muscular', type: 'test', difficulty: 'hard', questionText: 'Myastenia gravis hastalığının patofizyolojisi nedir?', options: ['Motor nöron dejenerasyonu', 'Nikotinik ACh reseptörlerine karşı otoantikor', 'Miyelin yıkımı', 'Kas distrofisi'], correctAnswer: 'Nikotinik ACh reseptörlerine karşı otoantikor', explanation: 'Myastenia gravis, nöromüsküler kavşaktaki nikotinik asetilkolin reseptörlerine karşı otoantikorların (IgG) oluştuğu otoimmün hastalıktır. Yorgunlukla artan kas güçsüzlüğü yapar.'),
    Question(id: 'px2_005', category: 'physiology', subcategory: 'muscular', type: 'test', difficulty: 'medium', questionText: 'Rigor mortis (ölüm katılığı) neden oluşur?', options: ['Kalsiyum fazlalığı', 'ATP tükenmesi nedeniyle aktin-miyozin bağı çözülemez', 'Asetilkolin fazlalığı', 'Laktik asit birikimi'], correctAnswer: 'ATP tükenmesi nedeniyle aktin-miyozin bağı çözülemez', explanation: 'Ölümden sonra ATP üretimi durur ve aktin-miyozin çapraz köprüleri çözülemez → kaslar sertleşir. 24-48 saat sonra otoliz ile çözülür.'),

    // ============================================================
    // HÜCRE FİZYOLOJİSİ (10 soru)
    // ============================================================
    Question(id: 'px2_006', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'medium', questionText: 'Hücre membranında madde taşınmasında ATP harcayan sisteme ne denir?', options: ['Pasif difüzyon', 'Osmoz', 'Aktif transport', 'Filtrasyon'], correctAnswer: 'Aktif transport', explanation: 'Aktif transport ATP harcayarak maddeleri konsantrasyon gradientine karşı taşır. Na⁺/K⁺ ATPaz pompası en bilinen örnektir: 3 Na⁺ dışarı, 2 K⁺ içeri pompalar.'),
    Question(id: 'px2_007', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'medium', questionText: 'Osmoz nedir?', options: ['Suyun yüksek konsantrasyondan düşüğe geçmesi', 'Suyun yarı geçirgen membrandan düşük çözünenden yüksek çözünene geçmesi', 'İyonların membranı geçmesi', 'Gazların difüzyonu'], correctAnswer: 'Suyun yarı geçirgen membrandan düşük çözünenden yüksek çözünene geçmesi', explanation: 'Osmozda su molekülleri yarı geçirgen membrandan, çözünen konsantrasyonunun düşük olduğu taraftan yüksek olduğu tarafa geçer (suyu seyreltmeye çalışır).'),
    Question(id: 'px2_008', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'hard', questionText: 'Na⁺/K⁺ ATPaz pompası her döngüde kaç iyon taşır?', options: ['2 Na⁺ dışarı, 3 K⁺ içeri', '3 Na⁺ dışarı, 2 K⁺ içeri', '1 Na⁺ dışarı, 1 K⁺ içeri', '4 Na⁺ dışarı, 4 K⁺ içeri'], correctAnswer: '3 Na⁺ dışarı, 2 K⁺ içeri', explanation: 'Na⁺/K⁺ ATPaz pompası elektrojenik bir pompadır: Her ATP molekülü başına 3 Na⁺ hücre dışına, 2 K⁺ hücre içine taşır. Bu istirahat membran potansiyelini korur.'),
    Question(id: 'px2_009', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'hard', questionText: 'Saltatorik (sıçrayıcı) iletim nedir?', options: ['İmpulsun akson boyunca sürekli yayılması', 'İmpulsun Ranvier boğumları arasında sıçraması', 'İmpulsun sinapslardan atlaması', 'İmpulsun dendritlerden sıçraması'], correctAnswer: 'İmpulsun Ranvier boğumları arasında sıçraması', explanation: 'Miyelinli sinir liflerinde aksiyon potansiyeli, miyelin kılıfının aralıkları olan Ranvier boğumları arasında sıçrar. Bu iletim hızını 50 kata kadar artırır.'),
    Question(id: 'px2_010', category: 'physiology', subcategory: 'nervous', type: 'test', difficulty: 'medium', questionText: 'Sempatik sinir sisteminin başlıca nörotransmitteri nedir?', options: ['Asetilkolin', 'Noradrenalin (norepinefrin)', 'Dopamin', 'GABA'], correctAnswer: 'Noradrenalin (norepinefrin)', explanation: 'Sempatik postganglionik nöronlar noradrenalin (norepinefrin) salgılar. İstisna: Ter bezlerini innerve eden sempatik lifler asetilkolin salgılar.'),

    // ============================================================
    // BİYOKİMYA BAZLI FİZYOLOJİ (12 soru)
    // ============================================================
    Question(id: 'px2_011', category: 'physiology', subcategory: 'digestive', type: 'test', difficulty: 'medium', questionText: 'Hücrelerde enerji üretiminin (aerobik solunum) gerçekleştiği organel hangisidir?', options: ['Ribozom', 'Lizozom', 'Mitokondri', 'Golgi aygıtı'], correctAnswer: 'Mitokondri', explanation: 'Mitokondri "hücrenin enerji santrali"dir. Krebs döngüsü ve oksidatif fosforilasyon burada gerçekleşir. Bir glukoz molekülünden ~36-38 ATP üretilir.'),
    Question(id: 'px2_012', category: 'physiology', subcategory: 'digestive', type: 'test', difficulty: 'hard', questionText: 'Glikoliz sonucunda bir glukoz molekülünden net kaç ATP üretilir?', options: ['1', '2', '4', '36'], correctAnswer: '2', explanation: 'Glikoliz (sitoplazmada) bir glukozdan 2 piruvat, net 2 ATP ve 2 NADH üretir. Oksijensiz koşullarda piruvat laktata dönüşür.'),
    Question(id: 'px2_013', category: 'physiology', subcategory: 'digestive', type: 'test', difficulty: 'hard', questionText: 'Krebs döngüsü (sitrik asit döngüsü) hücrenin neresinde gerçekleşir?', options: ['Sitoplazma', 'Çekirdek', 'Mitokondri matriks', 'Endoplazmik retikulum'], correctAnswer: 'Mitokondri matriks', explanation: 'Krebs döngüsü mitokondrinin matriksinde gerçekleşir. Asetil-CoA\'yı CO₂\'ye oksitler ve NADH, FADH₂ üretir. Bunlar elektron transport zincirinde ATP üretmek için kullanılır.'),
    Question(id: 'px2_014', category: 'physiology', subcategory: 'endocrine', type: 'test', difficulty: 'medium', questionText: 'Kan şekeri düştüğünde karaciğerde glikojeni glukoza çeviren sürece ne denir?', options: ['Glikoliz', 'Glikojenez', 'Glikojenoliz', 'Glukoneogenez'], correctAnswer: 'Glikojenoliz', explanation: 'Glikojenoliz: Glikojen → Glukoz (glikojen yıkımı). Glikojenez: Glukoz → Glikojen (glikojen sentezi). Glukoneogenez: Amino asit/laktat → Glukoz (yeni glukoz üretimi).'),
    Question(id: 'px2_015', category: 'physiology', subcategory: 'endocrine', type: 'test', difficulty: 'hard', questionText: 'Açlık durumunda yağ dokusundan salınan yağ asitlerinin karaciğerde oluşturduğu ürünlere ne denir?', options: ['Glukoz', 'Keton cisimleri', 'Laktat', 'Üre'], correctAnswer: 'Keton cisimleri', explanation: 'Uzun süreli açlık veya kontrolsüz diyabette, karaciğer yağ asitlerinden keton cisimleri (asetoasetat, beta-hidroksibutirat, aseton) üretir. Fazlalığı ketoasidoza yol açar.'),
    Question(id: 'px2_016', category: 'physiology', subcategory: 'renal', type: 'test', difficulty: 'medium', questionText: 'Proteinlerin yıkım ürünü olan amonyağın karaciğerde dönüştürüldüğü ve böbreklerden atılan madde nedir?', options: ['Kreatinin', 'Üre', 'Ürik asit', 'Bilirubin'], correctAnswer: 'Üre', explanation: 'Amino asitlerin deaminasyonuyla oluşan toksik amonyak, karaciğerde üre döngüsü ile daha az toksik üreye çevrilir ve böbreklerden atılır.'),
    Question(id: 'px2_017', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Hemoglobinin parçalanma ürünü olan ve sarılığa neden olan madde nedir?', options: ['Üre', 'Kreatinin', 'Bilirubin', 'Ürik asit'], correctAnswer: 'Bilirubin', explanation: 'Yaşlanan eritrositler dalakta parçalanır → Hemoglobin → Hem → Biliverdin → Bilirubin. İndirekt bilirubin karaciğerde konjuge edilip safra ile atılır. Birikmesi sarılık (ikter) yapar.'),
    Question(id: 'px2_018', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: 'Hemoglobin A1c (HbA1c) neyi gösterir?', options: ['Anlık kan şekerini', 'Son 2-3 aylık ortalama kan şekerini', 'Hemoglobin miktarını', 'Karaciğer fonksiyonunu'], correctAnswer: 'Son 2-3 aylık ortalama kan şekerini', explanation: 'HbA1c, glukozun hemoglobine geri dönüşümsüz bağlanmasını ölçer. Eritrosit ömrü ~120 gün olduğu için son 2-3 aylık glisemik kontrolü yansıtır. Diyabet takibinde kullanılır.'),

    // ============================================================
    // İMMÜN SİSTEM FİZYOLOJİSİ (10 soru)
    // ============================================================
    Question(id: 'px2_019', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Antikor üreten bağışıklık hücreleri hangileridir?', options: ['T lenfositler', 'B lenfositler (plazma hücreleri)', 'Makrofajlar', 'Nötrofiller'], correctAnswer: 'B lenfositler (plazma hücreleri)', explanation: 'B lenfositler antijen ile karşılaştığında plazma hücrelerine dönüşür ve antikor (immünoglobulin) üretir. T lenfositler hücresel bağışıklıkta görev alır.'),
    Question(id: 'px2_020', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Doğuştan (innate) bağışıklık ile kazanılmış (adaptive) bağışıklığın farkı nedir?', options: ['İkisi de aynıdır', 'Doğuştan: Hızlı, spesifik değil. Kazanılmış: Yavaş, spesifik, hafızalı', 'Doğuştan: Yavaş. Kazanılmış: Hızlı', 'İkisi de spesifiktir'], correctAnswer: 'Doğuştan: Hızlı, spesifik değil. Kazanılmış: Yavaş, spesifik, hafızalı', explanation: 'Doğuştan bağışıklık: Fiziksel bariyerler, nötrofiller, makrofajlar, NK hücreleri. Hızlı ama spesifik değil. Kazanılmış: T ve B lenfositler. Yavaş ama spesifik ve immünolojik hafızaya sahip.'),
    Question(id: 'px2_021', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: 'İmmünoglobulin sınıflarından hangisi plasenta geçişi yaparak fetüse pasif bağışıklık sağlar?', options: ['IgA', 'IgM', 'IgG', 'IgE'], correctAnswer: 'IgG', explanation: 'IgG, plasentayı geçebilen tek immünoglobulin sınıfıdır ve fetüse pasif bağışıklık sağlar. IgM ilk üretilen antikordur, IgA sekresyonlarda bulunur, IgE alerjide rol oynar.'),
    Question(id: 'px2_022', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'hard', questionText: 'Yardımcı T hücreleri (CD4+) hangi hücreleri aktive eder?', options: ['Sadece eritrositler', 'B lenfositler ve sitotoksik T hücreleri', 'Sadece nötrofiller', 'Sadece trombositler'], correctAnswer: 'B lenfositler ve sitotoksik T hücreleri', explanation: 'CD4+ yardımcı T hücreleri, bağışıklık yanıtının orkestra şefidir. B hücrelerini antikor üretmeye, CD8+ sitotoksik T hücrelerini öldürmeye yönlendirir. HIV bu hücreleri enfekte eder.'),
    Question(id: 'px2_023', category: 'physiology', subcategory: 'cardiovascular', type: 'test', difficulty: 'medium', questionText: 'Aşılama hangi bağışıklık tipini uyarır?', options: ['Doğal pasif', 'Doğal aktif', 'Yapay aktif', 'Yapay pasif'], correctAnswer: 'Yapay aktif', explanation: 'Aşılama yapay aktif bağışıklık sağlar: Zayıflatılmış/ölü antijen verilerek bağışıklık sistemi uyarılır ve hafıza hücreleri oluşur. Yapay pasif: Hazır antikor verilmesi (serum).'),
  ];
}

