    Question(id: 'phx2_001', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'SSRI grubu antidepresanların etki mekanizması nedir?', options: ['Dopamin geri alım inhibisyonu', 'Serotonin geri alım inhibisyonu', 'Noradrenalin geri alım inhibisyonu', 'MAO inhibisyonu'], correctAnswer: 'Serotonin geri alım inhibisyonu', explanation: 'SSRI\'lar (fluoksetin, sertralin, paroksetin) presinaptik nöronda serotonin geri alımını inhibe ederek sinaptik aralıkta serotonin düzeyini artırır. Depresyon ve anksiyete tedavisinde ilk seçenektir.'),
    Question(id: 'phx2_002', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Epilepsi tedavisinde nöbet eşiğini yükselten ilaçlara ne denir?', options: ['Antipsikotik', 'Antiepileptik (antikonvülzan)', 'Antidepresan', 'Anksiyolitik'], correctAnswer: 'Antiepileptik (antikonvülzan)', explanation: 'Antiepileptikler (valproat, karbamazepin, fenitoin, levetirasetam) nöbet eşiğini yükselterek epileptik nöbetleri önler. Na⁺ kanalı blokajı, GABA artırma gibi mekanizmalarla çalışır.'),
    Question(id: 'phx2_003', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Parkinson hastalığı tedavisinde dopamin öncüsü olarak kullanılan ilaç hangisidir?', options: ['Haloperidol', 'Levodopa (L-DOPA)', 'Diazepam', 'Fluoksetin'], correctAnswer: 'Levodopa (L-DOPA)', explanation: 'Levodopa, beyinde dopamine dönüşen öncü maddedir. Dopamin kan-beyin bariyerini geçemez ama levodopa geçer. Karbidopa ile birlikte verilir (periferik dekarboksilasyonu önler).'),
    Question(id: 'phx2_004', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Genel anestezi altında hasta neden ağrı duymaz?', options: ['Kaslar felç olur', 'SSS\'de bilinç, ağrı algısı ve refleksler baskılanır', 'Kalp durur', 'Sadece yerel uyuşma olur'], correctAnswer: 'SSS\'de bilinç, ağrı algısı ve refleksler baskılanır', explanation: 'Genel anestezi dört bileşenden oluşur: Bilinç kaybı (hipnoz), ağrı duymamazlık (analjezi), kas gevşemesi, refleks baskılanması. İnhalasyon (sevofluran) veya IV (propofol) ajanlarla sağlanır.'),

    // ============================================================
    // ENDOKRİN İLAÇLAR (8 soru)
    // ============================================================
    Question(id: 'phx2_005', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'easy', questionText: 'İnsülin hangi hastalıkta kullanılır?', options: ['Hipertansiyon', 'Diyabetes mellitus', 'Astım', 'Epilepsi'], correctAnswer: 'Diyabetes mellitus', explanation: 'İnsülin, Tip 1 diyabette (mutlaka) ve Tip 2 diyabette (oral ilaçlar yetersizse) kan şekerini düşürmek için kullanılır. Subkutan enjeksiyonla verilir.'),
    Question(id: 'phx2_006', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Levotiroksin ne için kullanılır?', options: ['Hipertiroidizm', 'Hipotiroidizm (tiroid hormon yerine koyma)', 'Diyabet', 'Hipertansiyon'], correctAnswer: 'Hipotiroidizm (tiroid hormon yerine koyma)', explanation: 'Levotiroksin (sentetik T4), hipotiroidizm tedavisinde tiroid hormonu yerine koyma (replasman) tedavisi olarak kullanılır. Hashimoto tiroiditi en sık neden.'),
    Question(id: 'phx2_007', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Kortikosteroidlerin uzun süreli kullanımında görülen yan etki hangisidir?', options: ['Hipotansiyon', 'Osteoporoz, hiperglisemi, immünsüpresyon', 'Hipoglisemi', 'Hipokalemi'], correctAnswer: 'Osteoporoz, hiperglisemi, immünsüpresyon', explanation: 'Kronik kortikosteroid kullanımı: Osteoporoz, Cushing görünümü, hiperglisemi, immünsüpresyon, peptik ülser, adrenal supresyon, miyopati, cilt incelmesi.'),
    Question(id: 'phx2_008', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Oral kontraseptifler (doğum kontrol hapı) hangi hormonları içerir?', options: ['İnsülin ve glukagon', 'Östrojen ve progesteron (sentetik)', 'Testosteron ve GH', 'T3 ve T4'], correctAnswer: 'Östrojen ve progesteron (sentetik)', explanation: 'Kombine oral kontraseptifler sentetik östrojen (etinil östradiol) ve progesteron (levonorgestrel vb.) içerir. Ovulasyonu baskılayarak gebeliği önler.'),

    // ============================================================
