    // ============================================================
    Question(id: 'phx2_009', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Kurşun zehirlenmesinde kullanılan antidot hangisidir?', options: ['Desferoksamin', 'EDTA (kalsiyum disodyum)', 'Nalokson', 'Atropin'], correctAnswer: 'EDTA (kalsiyum disodyum)', explanation: 'Kurşun zehirlenmesinde CaNa₂EDTA veya süksimerler (DMSA) kullanılır. Kurşun, hemoglobin sentezini bozar ve nörotoksiktir. Çocuklarda gelişim geriliğine neden olur.'),
    Question(id: 'phx2_010', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Karbon monoksit (CO) zehirlenmesinde tedavi nedir?', options: ['Nalokson', 'N-asetilsistein', '%100 oksijen ve hiperbarik oksijen', 'Atropin'], correctAnswer: '%100 oksijen ve hiperbarik oksijen', explanation: 'CO, hemoglobine O₂\'den 200 kat daha güçlü bağlanır (karboksihemoglobin). Tedavi: Yüksek akım %100 O₂ veya hiperbarik oksijen → CO\'nun hemoglobinden ayrılmasını hızlandırır.'),
    Question(id: 'phx2_011', category: 'pharmacology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Siyanür zehirlenmesinde antidot olarak kullanılan madde hangisidir?', options: ['Nalokson', 'Hidroksokobalamin (B12) veya sodyum tiyosülfat', 'Flumazenil', 'Pralidoksim'], correctAnswer: 'Hidroksokobalamin (B12) veya sodyum tiyosülfat', explanation: 'Siyanür mitokondride sitokrom oksidazı inhibe ederek aerobik solunumu durdurur. Hidroksokobalamin siyanürü bağlar, sodyum tiyosülfat ise rodanaz enzimi ile detoksifikasyonu artırır.'),
