class PathologyExtraQuestions2 {
  static final List<Question> questions = [
    // ============================================================
    // ORGAN PATOLOJİLERİ (15 soru)
    // ============================================================
    Question(id: 'ptx2_001', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Miyokard infarktüsünde (kalp krizi) en sık tıkanan arter hangisidir?', options: ['Sağ koroner arter', 'Sol sirkumfleks arter', 'LAD (sol ön inen arter)', 'Posterior desandan arter'], correctAnswer: 'LAD (sol ön inen arter)', explanation: 'LAD (sol ön inen arter), MI\'da en sık tıkanan arterdir (~40-50%). Sol ventrikül ön duvarını besler. Bu nedenle "dul yapan arter" (widow maker) olarak da bilinir.'),
    Question(id: 'ptx2_002', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'MI tanısında en spesifik biyobelirteç hangisidir?', options: ['CK-MB', 'Troponin I/T', 'LDH', 'Miyoglobin'], correctAnswer: 'Troponin I/T', explanation: 'Kardiyak troponin I ve T, miyokard hasarı için en spesifik ve en sensitif biyobelirteçlerdir. MI\'da 3-6 saat sonra yükselir ve 7-14 gün yüksek kalır.'),
    Question(id: 'ptx2_003', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Hepatit B virüsünün bulaşma yolları hangileridir?', options: ['Fekal-oral', 'Kan, cinsel temas, anneden bebeğe (perinatal)', 'Hava yolu', 'Su ve gıda'], correctAnswer: 'Kan, cinsel temas, anneden bebeğe (perinatal)', explanation: 'HBV, kan ve vücut sıvıları yoluyla bulaşır: Kontamine kan/iğne, korunmasız cinsel temas, anneden bebeğe (vertikal). Fekal-oral bulaşmaz.'),
    Question(id: 'ptx2_004', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Karaciğer sirozunun en sık nedeni hangisidir?', options: ['Hepatit A', 'Alkol kullanımı ve Hepatit C', 'İlaç toksisitesi', 'Wilson hastalığı'], correctAnswer: 'Alkol kullanımı ve Hepatit C', explanation: 'Dünyada sirozun en sık nedenleri kronik alkol kullanımı ve Hepatit C enfeksiyonudur. Siroz: Karaciğerin fibrozis ve rejeneratif nodüllerle yapısal bozulmasıdır.'),
    Question(id: 'ptx2_005', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Tip 1 diyabetes mellitus hangi mekanizmayla gelişir?', options: ['İnsülin direnci', 'Pankreatik beta hücrelerin otoimmün yıkımı', 'Glukagon fazlalığı', 'İnsülin reseptör defekti'], correctAnswer: 'Pankreatik beta hücrelerin otoimmün yıkımı', explanation: 'Tip 1 DM, Langerhans adacıklarındaki beta hücrelerin otoimmün yıkımı sonucu mutlak insülin eksikliğidir. Genellikle çocukluk/gençlik döneminde başlar.'),
    Question(id: 'ptx2_006', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Tip 2 diyabetes mellitus\'un temel mekanizması nedir?', options: ['Beta hücre yıkımı', 'İnsülin direnci ve göreceli insülin eksikliği', 'Glukoz emilim bozukluğu', 'Böbrek yetmezliği'], correctAnswer: 'İnsülin direnci ve göreceli insülin eksikliği', explanation: 'Tip 2 DM\'de hücreler insüline dirençlidir (insülin reseptör duyarlılığı azalmış). Obezite en önemli risk faktörüdür. Erişkin yaşta daha sıktır.'),
    Question(id: 'ptx2_007', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Hashimoto tiroiditi hangi tip hastalıktır?', options: ['Enfeksiyon', 'Neoplazi', 'Otoimmün', 'Metabolik'], correctAnswer: 'Otoimmün', explanation: 'Hashimoto tiroiditi, tiroid bezine karşı otoantikor üretilen (anti-TPO, anti-tiroglobulin) kronik otoimmün tiroidittir. Hipotiroidizmin en sık nedenidir.'),
    Question(id: 'ptx2_008', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Graves hastalığının patogenezi nedir?', options: ['Tiroid kanseri', 'TSH reseptörünü uyaran otoantikorlar', 'İyot eksikliği', 'Tiroidit'], correctAnswer: 'TSH reseptörünü uyaran otoantikorlar', explanation: 'Graves hastalığı: TSH reseptörüne bağlanıp aktive eden stimülan otoantikorlar (TSI) → Aşırı tiroid hormonu üretimi → Hipertiroidizm, egzoftalmi, diffüz guatr.'),
    Question(id: 'ptx2_009', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Anemi nedir?', options: ['Lökosit azlığı', 'Hemoglobin ve/veya eritrosit azlığı', 'Trombosit azlığı', 'Plazma azlığı'], correctAnswer: 'Hemoglobin ve/veya eritrosit azlığı', explanation: 'Anemi, kanın oksijen taşıma kapasitesinin azalmasıdır (Hb düşüklüğü). Demir eksikliği en sık nedendir. Yorgunluk, solukluk, taşikardi semptomları görülür.'),
    Question(id: 'ptx2_010', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Orak hücreli anemi hangi hemoglobin mutasyonuyla oluşur?', options: ['HbA → HbC', 'HbA → HbS (glutamik asit → valin)', 'HbA → HbF', 'HbA → HbE'], correctAnswer: 'HbA → HbS (glutamik asit → valin)', explanation: 'Orak hücreli anemi, beta-globin geninde nokta mutasyonu (glutamik asit → valin) sonucu HbS üretilmesidir. Düşük O₂\'de eritrositler orak şeklini alır ve damar tıkanıklığı yapar.'),
    Question(id: 'ptx2_011', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'Lösemi nedir?', options: ['Karaciğer kanseri', 'Kemik iliğinden kaynaklanan kan kanseri', 'Beyin tümörü', 'Lenf düğümü kanseri'], correctAnswer: 'Kemik iliğinden kaynaklanan kan kanseri', explanation: 'Lösemi, kemik iliğinde lökositlerin kontrolsüz çoğalmasıdır. Akut (ALL, AML) ve kronik (KLL, KML) tipleri vardır. Çocuklarda ALL en sık görülen kanserdir.'),
    Question(id: 'ptx2_012', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'DIC (Dissemine İntravasküler Koagülasyon) nedir?', options: ['Sadece pıhtılaşma', 'Sadece kanama', 'Yaygın pıhtılaşma ve ardından kanama (tüketim koagülopatisi)', 'Trombosit artışı'], correctAnswer: 'Yaygın pıhtılaşma ve ardından kanama (tüketim koagülopatisi)', explanation: 'DIC\'de yaygın küçük damar pıhtılaşması olur → pıhtılaşma faktörleri ve trombositler tükenir → paradoks olarak kanama başlar. Sepsis, travma, obstetrik komplikasyonlar tetikler.'),
    Question(id: 'ptx2_013', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'medium', questionText: 'İnme (stroke) tipleri hangileridir?', options: ['Kardiyak ve pulmoner', 'İskemik ve hemorajik', 'Akut ve kronik', 'Benign ve malign'], correctAnswer: 'İskemik ve hemorajik', explanation: 'İskemik inme (~85%): Beyin arterinin pıhtıyla tıkanması. Hemorajik inme (~15%): Beyin damarının kanaması. İskemik daha sık, hemorajik daha ölümcüldür.'),
    Question(id: 'ptx2_014', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Alzheimer hastalığının patolojik bulguları hangileridir?', options: ['Lewy cisimleri', 'Amiloid plaklar ve nörofibriler yumaklar', 'Hirano cisimleri', 'Pick cisimleri'], correctAnswer: 'Amiloid plaklar ve nörofibriler yumaklar', explanation: 'Alzheimer: Hücre dışı amiloid-beta plakları ve hücre içi hiperfosforile tau proteininden oluşan nörofibriler yumaklar. Serebral korteks ve hipokampusta nöron kaybı → ilerleyici demans.'),
    Question(id: 'ptx2_015', category: 'pathology', subcategory: 'general', type: 'test', difficulty: 'hard', questionText: 'Parkinson hastalığının patolojik bulgusu nedir?', options: ['Amiloid plaklar', 'Substantia nigrada dopaminerjik nöron kaybı ve Lewy cisimleri', 'Demiyelinizasyon', 'Granülom'], correctAnswer: 'Substantia nigrada dopaminerjik nöron kaybı ve Lewy cisimleri', explanation: 'Parkinson: Substantia nigrada dopaminerjik nöronların kaybı ve intranörönal Lewy cisimcikleri (alfa-sinüklein). Tremor, rijidite, bradikinezi, postural instabilite.'),
  ];
}
